probe_sources.native-send.c:
#include "id.h"
#include <assert.h>
#include <dlfcn.h>
#include <stdio.h>
#include <time.h>
int main(int argc,char **argv) {
 assert(argc==2);
 void *library=dlopen(argv[1],RTLD_NOW|RTLD_LOCAL);assert(library);
 const IdProtocol *(*boot)(const IdSeed *,size_t)=dlsym(library,"birnam_id_bootstrap_v2");assert(boot);
 IdSeed seeds[]={LIT("objectPrototype"),LIT("yourself")};
 const IdProtocol *id=boot(seeds,2);assert(id);
 Oop selectors[2];
 for(size_t i=0;i<2;i++) {Oop index=id_size(i);Oop name=id->message(id->root,id->seeds,id->at,&index,1);selectors[i]=id->message(id->root,name,id->intern,0,0);assert(!id_fault(selectors[i]));}
 Oop receiver=id->message(id->root,id->root,selectors[0],0,0);assert(!id_fault(receiver));
 for(size_t i=0;i<10000;i++)assert(id->message(id->root,receiver,selectors[1],0,0)==receiver);
 for(size_t sample=0;sample<5;sample++) {
  uint64_t start=clock_gettime_nsec_np(CLOCK_THREAD_CPUTIME_ID);
  for(size_t i=0;i<1000000;i++)assert(id->message(id->root,receiver,selectors[1],0,0)==receiver);
  uint64_t elapsed=clock_gettime_nsec_np(CLOCK_THREAD_CPUTIME_ID)-start;
  printf("%llu\n",(unsigned long long)elapsed);
 }
}
